cat > /tmp/load.py <<'EOF'
import csv, json, collections
from datetime import datetime, timezone
def ts(s): return datetime.strptime(s,"%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
def rd(f): return list(csv.DictReader(open(f)))
plan={r['run_id']:r for r in rd('plan.csv')}
planrows=rd('plan.csv'); assert len(planrows)==len(plan)
launch=rd('launch_log.csv')
launched={}
for r in launch:
    if r['run_id'] in launched:
        assert launched[r['run_id']]==(r['started_at'],r['worker']), r
    launched[r['run_id']]=(r['started_at'],r['worker'])
print('launch rows',len(launch),'unique',len(launched))
assert all(k in plan for k in launched)
rt=rd('runtime.csv'); runtime={}
for r in rt:
    if r['run_id'] in runtime: assert runtime[r['run_id']]==r['finished_at']
    runtime[r['run_id']]=r['finished_at']
print('runtime unique',len(runtime), set(runtime)==set(launched))
ev=rd('eval_results.csv'); evals={}
for r in ev:
    v=float(r['pass_rate'])
    if r['run_id'] in evals: assert evals[r['run_id']]==v,(r,evals[r['run_id']])
    evals[r['run_id']]=v
print('eval rows',len(ev),'unique',len(evals),'not launched',[k for k in evals if k not in launched])
ret=rd('retention_log.csv')
print('retention reasons',collections.Counter(r['reason'] for r in ret), 'unique',len({r['run_id'] for r in ret}))
print('retention in evals',[r['run_id'] for r in ret if r['run_id'] in evals])
print('retention not launched',[r['run_id'] for r in ret if r['run_id'] not in launched])
import glob
shard={}
for f in sorted(glob.glob('recovered/*.csv')):
    for r in rd(f):
        v=round(float(r['pass_rate_pct'])/100,4)
        if r['run_id'] in shard: assert abs(shard[r['run_id']]-v)<1e-9,(r,shard[r['run_id']])
        shard[r['run_id']]=v
print('shard unique',len(shard),'not launched',[k for k in shard if k not in launched])
print('shard in evals agree', all(abs(evals[k]-v)<1e-9 for k,v in shard.items() if k in evals), sum(k in evals for k in shard))
print('shard in retention', sum(k in {r['run_id'] for r in ret} for k in shard))
# INC-4471 window
w0,w1=ts('2026-06-27T00:00:00Z'),ts('2026-07-03T12:00:00Z')
inc1={k for k,(s,w) in launched.items() if w in('w03','w07') and w0<=ts(s)<=w1}
print('inc4471 runs',len(inc1),'in evals',sum(k in evals for k in inc1),'in ret',sum(k in {r['run_id'] for r in ret} for k in inc1),'in shard',sum(k in shard for k in inc1))
bd=[k for k,(s,w) in launched.items() if w in('w03','w07') and ts(s) in (w0,w1)]
print('boundary',bd)
# near boundary check: runs on w03/w07 just outside window in evals?
outside=[(k,s) for k,(s,w) in launched.items() if w in('w03','w07') and not(w0<=ts(s)<=w1) and k not in evals and k not in {r['run_id'] for r in ret}]
print('w03/w07 outside window unaccounted',outside)
w9={k for k,(s,w) in launched.items() if w=='w09'}
print('w09 runs',len(w9),'starts',sorted(launched[k][0] for k in w9)[:3],sorted(launched[k][0] for k in w9)[-3:])
print('w09 in evals/ret/shard',sum(k in evals for k in w9),sum(k in {r['run_id'] for r in ret} for k in w9),sum(k in shard for k in w9))
retids={r['run_id'] for r in ret}
unacc=[k for k in launched if k not in evals and k not in retids and k not in inc1 and k not in w9]
print('unaccounted launched',unacc)
# workers
print(collections.Counter(w for s,w in launched.values()))
# digest check
dig={r['date']:(int(r['n_runs']),float(r['sum_pass_rate'])) for r in rd('daily_digest.csv')}
fin=collections.Counter(runtime[k][:10] for k in launched)
print('digest vs runtime', all(dig.get(d,(0,0))[0]==n for d,n in fin.items()), set(dig)-set(fin), {d:(fin[d],dig[d][0]) for d in dig if fin[d]!=dig[d][0]})
print('finish range',min(runtime.values()),max(runtime.values()))
# shard_file_lost check: worker w01 and finish date 07-04?
for r in ret:
    if r['reason']=='shard_file_lost':
        k=r['run_id']; assert launched[k][1]=='w01' and runtime[k][:10]=='2026-07-04',(r,launched[k],runtime[k])
# below floor: dropped_at vs finished_at
for r in ret:
    if r['reason']=='below_retention_floor':
        k=r['run_id']
        if r['dropped_at']!=runtime[k]: print('drop!=finish',r,runtime[k])
# w01 07-04 runs: all in ret shard lost or evals?
w01=[k for k in launched if launched[k][1]=='w01' and runtime[k][:10]=='2026-07-04']
print('w01 0704',len(w01),collections.Counter('ev' if k in evals else next(r['reason'] for r in ret if r['run_id']==k) for k in w01))
EOF
python3 /tmp/load.py
